contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 probe) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(probe >= 0);
        uint256 cBalBefore = address(c).balance;
        uint256 thisBalBefore = address(this).balance;
        // caller has never deposited, so credit is zero
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(!reverted && address(c).balance == cBalBefore && address(this).balance == thisBalBefore);
    }
    receive() external payable {}
}

