// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 probe) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(probe >= 0);
        uint256 cBalBefore = address(c).balance;
        uint256 thisBalBefore = address(this).balance;
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && address(c).balance == cBalBefore && address(this).balance == thisBalBefore);
    }

    function testFuzz_run(uint256 probe) public {
        _run(probe);
    }

    receive() external payable {}
}
